effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
 //////////////////////////
 vec4 newLayer( vec4 a, vec4 b) { return a * (1.0 - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.0)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

     float rand(vec2 p)
     {
         float EVO = autop? PROGRESS + (acTime*SPEED) : PROGRESS;
         float t = floor(EVO*10.0) / 10.0;
         return fract(sin(dot(p, vec2(t * 12.9898, t * 78.233))) * 43758.5453);
     }

     float noise(vec2 uv, float blockiness)
     {   
         vec2 lv = fract(uv);
         vec2 id = floor(uv);

         float n1 = rand(id);
         float n2 = rand(id+vec2(1,0));
         float n3 = rand(id+vec2(0,1));
         float n4 = rand(id+vec2(1,1));

         vec2 u = smoothstep(0.0, 1.0 + blockiness, lv);

         return mix(mix(n1, n2, u.x), mix(n3, n4, u.x), u.y);
     }

     float fbm(vec2 uv, int count, float blockiness, float complexity)
     {
         float val = 0.0;
         float amp = 0.5;

         while(count != 0)
         {
         	val += amp * noise(uv, blockiness);
             amp *= 0.5;
             uv *= complexity;    
             count--;
         }

         return val;
     }
 //////////////////////////
     void main() {
     if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);

     vec2 TanRyu;
     TanRyu = acScreenNorm.st; 

     /////////////////////////

 	vec4 fragColor;

         vec2 uv = TanRyu;

         vec2 a = vec2(uv.x * (iResolution.x / iResolution.y), uv.y);
         vec2 uv2 = vec2(a.x / iResolution.x, exp(a.y));
         vec2 id = floor(uv * AMOUNT);
         // if(L2S) { id = l2s(id); }

             vec2 scaleVec;
             scaleVec = vec2(scale*stretch.x,scale*stretch.y);
             uv2 /= scaleVec;

         float shift = glitchAmplitude * pow(fbm(uv2, int(rand(id) * DISTORT), 
                       glitchBlockiness, glitchNarrowness), glitchMinimizer);
         float scanline = abs(cos(uv.y * 400.0));
         scanline = smoothstep(0.0, 2.0, scanline);
         shift = smoothstep(0.00001, STEP, shift);

             float colR;
             if (rcolor) { colR = texture2DCv(inputImg.texture, vec2(uv.x + shift, uv.y)).r * (1. - shift); }
             else { colR = texture2DCv(inputImg.texture, vec2(uv.x - shift, uv.y)).r * (1. - shift); }

             float colG;
             if (gcolor) { colG = texture2DCv(inputImg.texture, vec2(uv.x + shift, uv.y)).g * (1. - shift); }
             else { colG = texture2DCv(inputImg.texture, vec2(uv.x - shift, uv.y)).g * (1. - shift); }

             float colB;
             if (bcolor) { colB = texture2DCv(inputImg.texture, vec2(uv.x + shift, uv.y)).b * (1. - shift); }
             else { colB = texture2DCv(inputImg.texture, vec2(uv.x - shift, uv.y)).b * (1. - shift); }

     vec3 f = vec3(colR, colG, colB);
     vec4 factor = vec4(f, texColor.a) * alpha;
     if(OFFSIDE) { factor *= texColor.a; }

     vec4 resultfinal = newLayer(texColor*texColor.a,factor);

 	gl_FragColor = resultfinal;
       }
     }
